from typing import List


class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = []
        for i, x in enumerate(nums):
            if x == 0:
                result.append(0)
            else:
                if x > 0:
                    result.append(nums[(i + x) % n])
                else:
                    result.append(nums[n - (-x - i) % n])
        return result
